	/*
     * @param	event CreateProductEvent
     */
    @EventHandler( payloadType=CreateProductEvent.class )
    public void handle( CreateProductEvent event) {
	    LOGGER.info("handling CreateProductEvent - " + event );
	    Product entity = new Product();
            entity.setProductId( event.getProductId() );
            entity.setName( event.getName() );
            entity.setSlug( event.getSlug() );
            entity.setAsActive( event.getAsActive() );
            entity.setProductType( event.getProductType() );
            entity.setDefaultTaxClass( event.getDefaultTaxClass() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllProduct( entity );
    }

    /*
     * @param	event UpdateProductEvent
     */
    @EventHandler( payloadType=UpdateProductEvent.class )
    public void handle( UpdateProductEvent event) {
    	LOGGER.info("handling UpdateProductEvent - " + event );
    	
	    Product entity = new Product();
            entity.setProductId( event.getProductId() );
            entity.setName( event.getName() );
            entity.setSlug( event.getSlug() );
            entity.setAsActive( event.getAsActive() );
            entity.setBrand( event.getBrand() );
            entity.setCategories( event.getCategories() );
            entity.setVariants( event.getVariants() );
            entity.setMediaAssets( event.getMediaAssets() );
            entity.setReviews( event.getReviews() );
            entity.setSeller( event.getSeller() );
            entity.setProductType( event.getProductType() );
            entity.setDefaultTaxClass( event.getDefaultTaxClass() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindProduct( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllProduct( entity );        
    }
    
